class EchoingMines(MineBehavior):
    """
    When a mine is revealed, any adjacent unrevealed cells that are NOT mines
    are also revealed. This can lead to rapid board clearing but also makes
    it harder to deduce mine locations based on numbers.
    """

    def on_post_action(self, board, game, action):
        if not action.get("hit_mine") and not action.get("newly_revealed"):
            return

        # We care about the cells that were JUST revealed, either by the player
        # or by a previous cascade.
        cells_to_check = set(action.get("newly_revealed", []))
        if action["action"] == "reveal":
            cells_to_check.add(action["coords"])

        newly_revealed_cells_in_this_turn = set()

        for r, c in list(cells_to_check): # Use list() to allow modification of cells_to_check
            for nr, nc in board.neighbors(r, c):
                if board.in_bounds(nr, nc):
                    target_cell = board.grid[nr][nc]
                    if not target_cell.is_revealed and not target_cell.is_mine and not target_cell.is_flagged:
                        # This is a safe cell adjacent to a revealed mine. Reveal it.
                        if board.grid[nr][nc].adjacent_mines == 0:
                            # If it's a blank, cascade the reveal.
                            cascade_queue = deque([(nr, nc)])
                            while cascade_queue:
                                queu_r, queu_c = cascade_queue.popleft()
                                if board.grid[queu_r][queu_c].is_revealed: # Already revealed by another path
                                    continue
                                board.grid[queu_r][queu_c].is_revealed = True
                                newly_revealed_cells_in_this_turn.add((queu_r, queu_c))
                                if board.grid[queu_r][queu_c].adjacent_mines == 0:
                                    for nnr, nnc in board.neighbors(queu_r, queu_c):
                                        if board.in_bounds(nnr, nnc) and not board.grid[nnr][nnc].is_revealed and not board.grid[nnr][nnc].is_mine and not board.grid[nnr][nnc].is_flagged:
                                            cascade_queue.append((nnr, nnc))
                        else:
                            # It's a number, just reveal it.
                            board.grid[nr][nc].is_revealed = True
                            newly_revealed_cells_in_this_turn.add((nr, nc))

        # Add any newly revealed cells to the action's list for the game to re-check state.
        # This is crucial for chain reactions and cascades to be properly handled.
        action["newly_revealed"].extend(list(newly_revealed_cells_in_this_turn))

class DepthChargeReveal(RevealStrategy):
    """
    When a mine is revealed, it explodes and reveals all cells within a 2-cell radius.
    This creates a larger cascade effect, but also a more dangerous one if a mine is hit.
    """

    def reveal(self, board: Board, r: int, c: int) -> list[tuple[int, int]]:
        cell = board.grid[r][c]
        revealed_cells = []

        if cell.is_mine:
            # If a mine is revealed, trigger the depth charge effect
            for dr in range(-2, 3):
                for dc in range(-2, 3):
                    nr, nc = r + dr, c + dc
                    if board.in_bounds(nr, nc):
                        target_cell = board.grid[nr][nc]
                        if not target_cell.is_revealed and not target_cell.is_flagged:
                            if target_cell.is_mine:
                                board.reveal_mine(nr, nc) # Mark as revealed mine
                            else:
                                target_cell.is_revealed = True
                            if (nr, nc) not in revealed_cells:
                                revealed_cells.append((nr, nc))
            # In this variant, hitting a mine doesn't immediately end the game, but it does cause damage
            # The game controller will handle player damage based on 'mine_damage'.
            return revealed_cells

        # If not a mine, perform a standard cascade reveal
        if cell.adjacent_mines > 0:
            cell.is_revealed = True
            revealed_cells.append((r, c))
            return revealed_cells

        queue: deque[tuple[int, int]] = deque([(r, c)])
        visited: set[tuple[int, int]] = {(r, c)}

        while queue:
            cr, cc = queue.popleft()
            curr = board.grid[cr][cc]
            if curr.is_revealed or curr.is_flagged or curr.is_mine:
                continue
            curr.is_revealed = True
            if (cr, cc) not in revealed_cells:
                revealed_cells.append((cr, cc))
            if curr.adjacent_mines == 0:
                for nr, nc in board.neighbors(cr, cc):
                    if board.in_bounds(nr, nc) and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append((nr, nc))
        return revealed_cells

class ProximityReveal(RevealStrategy):
    """
    Reveals the clicked cell and any adjacent cells with the same number of adjacent mines.
    This encourages identifying clusters of cells with similar mine counts.
    """

    def reveal(self, board: Board, r: int, c: int) -> list[tuple[int, int]]:
        cell = board.grid[r][c]
        if cell.is_revealed or cell.is_flagged:
            return []

        cell.is_revealed = True
        revealed_cells = [(r, c)]
        target_adjacent_mines = cell.adjacent_mines

        if target_adjacent_mines == 0:
            # If it's a zero, cascade like standard minesweeper to ensure progress
            queue: deque[tuple[int, int]] = deque([(r, c)])
            visited: set[tuple[int, int]] = {(r, c)}
            while queue:
                cr, cc = queue.popleft()
                curr = board.grid[cr][cc]
                if curr.is_revealed or curr.is_flagged or curr.is_mine:
                    continue
                curr.is_revealed = True
                revealed_cells.append((cr, cc))
                if curr.adjacent_mines == 0:
                    for nr, nc in board.neighbors(cr, cc):
                        if board.in_bounds(nr, nc) and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))
        else:
            # Reveal adjacent cells with the same mine count
            for nr, nc in board.neighbors(r, c):
                if board.in_bounds(nr, nc):
                    neighbor_cell = board.grid[nr][nc]
                    if not neighbor_cell.is_revealed and not neighbor_cell.is_flagged and neighbor_cell.adjacent_mines == target_adjacent_mines:
                        neighbor_cell.is_revealed = True
                        revealed_cells.append((nr, nc))

        return revealed_cells

class ProximityReveal(RevealStrategy):
    """
    Reveals the clicked cell and any adjacent cells with the same number of adjacent mines.
    This encourages players to identify groups of cells with the same difficulty level.
    """

    def reveal(self, board: Board, r: int, c: int) -> list[tuple[int, int]]:
        cell = board.grid[r][c]
        if cell.is_revealed or cell.is_flagged:
            return []

        target_adjacent_mines = cell.adjacent_mines
        cell.is_revealed = True
        revealed: list[tuple[int, int]] = [(r, c)]

        cells_to_check: deque[tuple[int, int]] = deque([(r, c)])
        visited: set[tuple[int, int]] = {(r, c)}

        while cells_to_check:
            cr, cc = cells_to_check.popleft()
            current_cell = board.grid[cr][cc]

            if current_cell.adjacent_mines == target_adjacent_mines and not current_cell.is_revealed and not current_cell.is_flagged and not current_cell.is_mine:
                current_cell.is_revealed = True
                revealed.append((cr, cc))

                # Add neighbors to check if they are also part of this proximity group
                for nr, nc in board.neighbors(cr, cc):
                    if board.in_bounds(nr, nc) and (nr, nc) not in visited:
                        neighbor_cell = board.grid[nr][nc]
                        # Only add neighbors that *could* be part of the proximity group or lead to it
                        # This prevents infinite loops and unnecessary checks while still exploring contiguous areas
                        if neighbor_cell.adjacent_mines == target_adjacent_mines or neighbor_cell.adjacent_mines == 0:
                             visited.add((nr, nc))
                             cells_to_check.append((nr, nc))
            elif current_cell.adjacent_mines == 0:
                # If it's a zero, explore its neighbors to potentially find more of the target group
                for nr, nc in board.neighbors(cr, cc):
                     if board.in_bounds(nr, nc) and (nr, nc) not in visited:
                        neighbor_cell = board.grid[nr][nc]
                        if neighbor_cell.adjacent_mines == target_adjacent_mines or neighbor_cell.adjacent_mines == 0:
                            visited.add((nr, nc))
                            cells_to_check.append((nr, nc))

        # After the initial proximity reveal, perform a cascade reveal on any newly revealed zero cells
        # This ensures that contiguous zero areas are still cleared efficiently.
        cascading_revealed: list[tuple[int, int]] = []
        queue: deque[tuple[int, int]] = deque()

        for rev_r, rev_c in revealed:
            if board.grid[rev_r][rev_c].adjacent_mines == 0:
                queue.append((rev_r, rev_c))
                # Ensure we don't re-reveal cells already in the initial 'revealed' list unnecessarily
                # and prevent cycles by marking them as visited for this cascade phase
                for nbr_r, nbc in board.neighbors(rev_r, rev_c):
                    if board.in_bounds(nbr_r, nbc) and not board.grid[nbr_r][nbc].is_revealed and not board.grid[nbr_r][nbc].is_flagged:
                        board.grid[nbr_r][nbc].is_revealed = True
                        cascading_revealed.append((nbr_r, nbc))
                        queue.append((nbr_r, nbc))

        # Standard cascade reveal for zero cells
        cascade_visited: set[tuple[int, int]] = set()
        while queue:
            cr, cc = queue.popleft()
            curr_cell = board.grid[cr][cc]

            if curr_cell.is_revealed or curr_cell.is_flagged or curr_cell.is_mine:
                continue

            curr_cell.is_revealed = True
            if (cr, cc) not in revealed and (cr, cc) not in cascading_revealed: # Avoid adding duplicates
                revealed.append((cr, cc))

            if curr_cell.adjacent_mines == 0:
                for nr, nc in board.neighbors(cr, cc):
                    if board.in_bounds(nr, nc) and (nr, nc) not in cascade_visited and not board.grid[nr][nc].is_revealed and not board.grid[nr][nc].is_flagged:
                        cascade_visited.add((nr, nc))
                        queue.append((nr, nc))
                        if (nr, nc) not in revealed and (nr, nc) not in cascading_revealed:
                            board.grid[nr][nc].is_revealed = True
                            revealed.append((nr, nc))

        return revealed

class StrategicProximityReveal(RevealStrategy):
    """
    When a cell is revealed, if it has adjacent mines, it also reveals all its
    unrevealed, unflagged neighbors that are NOT mines. This encourages strategic
    clearing around numbered cells.
    """

    def reveal(self, board: Board, r: int, c: int) -> list[tuple[int, int]]:
        cell = board.grid[r][c]
        revealed_cells = []

        if cell.is_revealed or cell.is_flagged:
            return []

        cell.is_revealed = True
        revealed_cells.append((r, c))

        if cell.adjacent_mines > 0:
            for nr, nc in board.neighbors(r, c):
                neighbor_cell = board.grid[nr][nc]
                if not neighbor_cell.is_revealed and not neighbor_cell.is_flagged and not neighbor_cell.is_mine:
                    neighbor_cell.is_revealed = True
                    revealed_cells.append((nr, nc))

        return revealed_cells
